c='p6';B='CSDL 5'
S=[]
S.append(TITLE('TIN HỌC · CƠ SỞ DỮ LIỆU 5','AN TOÀN, BẢO MẬT<br>VÀ PHÂN QUYỀN CSDL','Bảo mật và an toàn dữ liệu, nguyên tắc quyền tối thiểu, nhóm người dùng, GRANT và REVOKE, sao lưu – phục hồi, các mối nguy và cách phòng tránh.',['bảo mật','an toàn','GRANT','REVOKE','sao lưu']))
S.append(goals(c,B,['Phân biệt <b>bảo mật</b> và <b>đảm bảo an toàn</b> dữ liệu.','Áp dụng <b>nguyên tắc quyền tối thiểu</b> để thiết kế phân quyền.','Viết đúng <b>GRANT</b> và <b>REVOKE</b> (nhóm lệnh DCL).','Nêu các biện pháp: <b>xác thực, phân quyền, mã hoá, sao lưu, ghi nhật kí</b>.','Nhận biết các <b>mối nguy</b> và biện pháp phòng tránh.'],['Bảo mật và an toàn','Phân quyền','GRANT, REVOKE','Thiết kế quyền','Biện pháp bảo vệ']))
S.append(S2(c,B+' · 1','Bảo mật và an toàn dữ liệu',card('Hai mục tiêu khác nhau',P('<b>Bảo mật</b>: <b>ngăn truy cập trái phép</b>, chỉ đúng người, đúng quyền mới xem / sửa được.','<b>An toàn dữ liệu</b>: bảo đảm dữ liệu <b>không bị mất, hỏng</b> và <b>khôi phục được</b> khi có sự cố (hỏng đĩa, mất điện, thao tác nhầm).','Hai việc <b>bổ sung nhau</b> chứ không giống nhau.')),T(tr('','Bảo mật','An toàn dữ liệu',h=True)+tr('Mục tiêu','chống <b>truy cập trái phép</b>','chống <b>mất, hỏng</b> dữ liệu')+tr('Biện pháp','mật khẩu, <b>phân quyền</b>, mã hoá','<b>sao lưu</b>, phục hồi, kiểm soát giao dịch')+tr('Tình huống','kẻ lạ đọc dữ liệu khách hàng','ổ đĩa hỏng, xoá nhầm'))+KEY('Chính sách bảo mật gồm: <b>lập danh sách nhóm người dùng và quyền hạn</b> của từng nhóm.')))
S.append(S2(c,B+' · 1','Các mối nguy với CSDL',card('Từ trong và ngoài',T(tr('Mối nguy','Ví dụ','Phòng tránh',h=True)+tr('truy cập trái phép','đoán mật khẩu','mật khẩu mạnh, <b>xác thực</b>')+tr('lạm quyền','nhân viên xoá dữ liệu','<b>quyền tối thiểu</b>')+tr('tiêm SQL (SQL injection)','nhập mã độc vào ô','kiểm tra, tham số hoá')+tr('mất, hỏng dữ liệu','hỏng đĩa, thao tác nhầm','<b>sao lưu</b> định kì')+tr('nghe lén','đọc dữ liệu trên mạng','<b>mã hoá</b>, HTTPS'))),KEY('Không có một biện pháp duy nhất: cần <b>kết hợp nhiều lớp</b> bảo vệ.')))
S.append(S2(c,B+' · 2','Phân quyền và nhóm người dùng',card('Mỗi người một quyền phù hợp',P('<b>Phân quyền</b>: quy định mỗi người dùng (hay nhóm) được <b>làm những thao tác nào</b> trên đối tượng nào.','Quyền thường gặp: <b>SELECT</b> (xem), <b>INSERT</b> (thêm), <b>UPDATE</b> (sửa), <b>DELETE</b> (xoá), <b>CREATE / ALTER / DROP</b> (cấu trúc), <b>ALL</b> (mọi quyền).','<b>Nguyên tắc quyền tối thiểu</b>: chỉ cấp quyền <b>vừa đủ</b> để làm việc.')),T(tr('Nhóm','Quyền hợp lí',h=True)+tr('Khách (chưa đăng nhập)','<b>SELECT</b>')+tr('Người đóng góp','SELECT + <b>INSERT</b>')+tr('Quản lí nội dung','SELECT, INSERT, <b>UPDATE, DELETE</b>')+tr('Quản trị viên','toàn quyền (rất ít người)'))+KEY('Cho mọi người quyền ALL “cho tiện” là <b>sai</b>: vi phạm quyền tối thiểu.')))
S.append(S2(c,B+' · 2','Ví dụ thiết kế: website âm nhạc',card('Yêu cầu',P('Mọi người <b>xem bản nhạc không cần đăng nhập</b>.','Một nhóm được <b>thêm</b> dữ liệu nhưng <b>không được sửa / xoá</b>.','Nhóm quản lí được <b>cập nhật, xoá</b>.')),T(tr('Phương án','Đánh giá',h=True)+tr('Khách SELECT; nhóm thêm SELECT+INSERT; quản lí thêm UPDATE, DELETE','<b>Đúng</b>: quyền tối thiểu')+tr('Chỉ INSERT cho tất cả','Sai: khách không xem được')+tr('ALL cho tất cả','Sai: ai cũng xoá được')+tr('Một tài khoản chung cho mọi nhóm','Sai: không phân biệt được người dùng'))))
S.append(S2(c,B+' · 3','GRANT: cấp quyền',card('Cú pháp',P('<code>GRANT quyền ON đối_tượng TO người_dùng;</code>','Đối tượng: <code>music.*</code> (mọi bảng trong CSDL music), <code>music.bannhac</code> (một bảng).','GRANT/REVOKE thuộc nhóm <b>DCL</b> (Data Control Language): ngôn ngữ <b>kiểm soát quyền</b>.')),CODE('-- cho guest chỉ được đọc\nGRANT SELECT ON music.* TO guest;\n\n-- nhóm thêm dữ liệu\nGRANT SELECT, INSERT\n  ON music.bannhac TO nhom_them;',21)+KEY('Cho <b>guest chỉ đọc</b>: <b>GRANT SELECT ON music.* TO guest;</b>')))
S.append(S2(c,B+' · 3','REVOKE: thu hồi quyền',card('Cú pháp',P('<code>REVOKE quyền ON đối_tượng FROM người_dùng;</code>','Chú ý <b>FROM</b> (khác TO của GRANT).')),CODE('-- thu hồi quyền CREATE, ALTER\nREVOKE CREATE, ALTER\n  ON music.bannhac FROM guest;',21)+KEY('Thu hồi <b>CREATE, ALTER</b>: <b>REVOKE CREATE, ALTER ON music.bannhac FROM guest;</b>')))
S.append(TB(c,B+' · 3','Phân biệt GRANT và REVOKE',['','GRANT','REVOKE'],[['<b>Tác dụng</b>','<b>cấp</b> quyền','<b>thu hồi</b> quyền'],['<b>Từ nối</b>','<code>… ON đối_tượng <b>TO</b> người_dùng</code>','<code>… ON đối_tượng <b>FROM</b> người_dùng</code>'],['<b>Nhóm lệnh</b>','DCL','DCL'],['<b>Ví dụ</b>','<code>GRANT SELECT ON music.* TO guest;</code>','<code>REVOKE CREATE ON music.bannhac FROM guest;</code>']],note=KEY('Sai thường gặp: dùng <b>SET</b>, <b>DROP</b>, hoặc đảo GRANT ↔ REVOKE.')))
S.append(S2(c,B+' · 4','Sao lưu và phục hồi',card('An toàn dữ liệu',P('<b>Sao lưu (backup)</b> định kì ra nơi khác (đĩa, đám mây); thử <b>phục hồi</b> để chắc chắn bản sao dùng được.','Quy tắc 3-2-1: <b>3</b> bản, <b>2</b> loại phương tiện, <b>1</b> bản ở nơi khác.','<b>Ghi nhật kí (log)</b>: lưu lại mọi thay đổi để truy vết và phục hồi.')),FLOW([('Dữ liệu','đang dùng'),('Sao lưu','định kì'),('Sự cố','hỏng, xoá nhầm'),('Phục hồi','từ bản sao')],520,'#2E7D32',20)+KEY('Sao lưu là biện pháp của <b>an toàn dữ liệu</b>, <b>không phải</b> của bảo mật.')))
S.append(S2(c,B+' · 4','Xác thực, mã hoá và nhật kí',card('Các lớp bảo vệ',P('<b>Xác thực</b>: xác minh danh tính (mật khẩu, mã OTP, vân tay).','<b>Mã hoá</b>: biến dữ liệu thành dạng không đọc được nếu không có khoá; dùng cho đường truyền (HTTPS) và dữ liệu lưu trữ.','<b>Không lưu mật khẩu dạng rõ</b>: lưu bản <b>băm</b> (hash).','<b>Nhật kí truy cập</b>: ai làm gì, lúc nào.')),KEY('Bảo vệ nhiều lớp: <b>xác thực → phân quyền → mã hoá → nhật kí → sao lưu</b>.')))
S.append(S2(c,B+' · 4','SQL injection: ví dụ đơn giản',card('Kẻ gian chèn mã vào ô nhập',P('Nếu ghép trực tiếp chuỗi người dùng nhập vào câu SQL, kẻ gian nhập <code>&#39; OR &#39;1&#39;=&#39;1&#39; --</code> để biến điều kiện thành luôn đúng và <b>bỏ qua phần mật khẩu</b>.','Phòng tránh: <b>câu lệnh tham số hoá</b>, kiểm tra đầu vào, quyền tối thiểu cho tài khoản ứng dụng.')),CODE("-- câu gốc: ten='<nhập>' AND mk='<nhập>'\n-- kẻ gian nhập ten:  ' OR '1'='1' --\nSELECT * FROM u\nWHERE ten='' OR '1'='1' -- ' AND mk='x'\n-- phần sau dấu -- bị bỏ qua!",17)+RES(OUT(SQLRUN("CREATE TABLE u(ten TEXT, mk TEXT); INSERT INTO u VALUES('admin','sec');","SELECT * FROM u WHERE ten='' OR '1'='1' -- ' AND mk='x'"),22),'Không cần mật khẩu vẫn lấy được dòng admin')+KEY('Không bao giờ ghép trực tiếp chuỗi người dùng vào SQL.')))
S.append(SELF(c,B+' · 5','Tự kiểm tra 1: bảo mật hay an toàn?','Xếp mỗi việc vào “bảo mật” hoặc “an toàn dữ liệu”: (a) đặt mật khẩu; (b) sao lưu hằng ngày; (c) GRANT SELECT cho khách; (d) phục hồi sau khi hỏng đĩa.','',P('(a) <b>Bảo mật</b>.','(b) <b>An toàn dữ liệu</b>.','(c) <b>Bảo mật</b> (phân quyền).','(d) <b>An toàn dữ liệu</b>.'),22))
S.append(SELF(c,B+' · 5','Tự kiểm tra 2: viết lệnh','Viết lệnh cho guest chỉ được đọc mọi bảng trong CSDL music, rồi thu hồi quyền CREATE, ALTER trên bảng bannhac.','',P('<code>GRANT SELECT ON music.* TO guest;</code>','<code>REVOKE CREATE, ALTER ON music.bannhac FROM guest;</code>','GRANT dùng <b>TO</b>, REVOKE dùng <b>FROM</b>.'),20))
S.append(SELF(c,B+' · 5','Tự kiểm tra (HSG): đúng hay sai?','(a) Phân quyền giúp mỗi người chỉ làm được thao tác được cấp. (b) Cấp toàn quyền cho mọi người là tốt nhất. (c) Sao lưu định kì giúp khôi phục khi sự cố. (d) Kiểm soát giao dịch chỉ cần khi CSDL ở một máy. (e) Mật khẩu nên lưu dạng rõ.','',P('(a) <b>Đúng</b>.','(b) <b>Sai</b>: vi phạm quyền tối thiểu.','(c) <b>Đúng</b>.','(d) <b>Sai</b>: nhiều người truy cập đồng thời đều cần.','(e) <b>Sai</b>: lưu bản băm.'),20))
S+=END(c,B,['<b>Bảo mật</b> = chống truy cập trái phép; <b>an toàn</b> = không mất, khôi phục được.','<b>Quyền tối thiểu</b>: mỗi nhóm chỉ có quyền cần thiết.','<b>GRANT … TO</b> cấp; <b>REVOKE … FROM</b> thu hồi (DCL).','Biện pháp: xác thực, phân quyền, mã hoá, <b>sao lưu</b>, nhật kí.','Phòng SQL injection: tham số hoá, kiểm tra đầu vào.'],[('Cấp quyền đọc','GRANT SELECT'),('Thu hồi quyền','REVOKE'),('Khôi phục dữ liệu','sao lưu'),('Che dữ liệu khi truyền','mã hoá / HTTPS')],'Cấp ALL cho mọi người; dùng chung một tài khoản; nhầm TO với FROM; coi sao lưu là bảo mật.',['<b>Vai trò (role)</b> gom quyền.','<b>Chính sách mật khẩu</b>.','<b>Kiểm toán</b> (audit).'],['<b>Mô hình RBAC</b>.','<b>Mã hoá cột</b>.','<b>Kế hoạch khôi phục thảm hoạ</b>.'],
 [('Lệnh cấp quyền?',),('Lệnh thu hồi quyền?',),('Quyền chỉ xem?',),('Sao lưu thuộc nhóm nào?',),('Nguyên tắc cấp quyền?',)],
 [('<b>GRANT</b>.',),('<b>REVOKE</b>.',),('<b>SELECT</b>.',),('<b>An toàn dữ liệu</b>.',),('<b>Quyền tối thiểu</b>.',)],
 [('Mức 1. Cho guest quyền đọc bảng sach.',),('Mức 1. Phân loại: mật khẩu, sao lưu, phân quyền, phục hồi.',),('Mức 2. Thiết kế quyền cho khách, thành viên, quản lí của một thư viện.',),('Mức 2. Thu hồi quyền DELETE của nhom_them trên bảng bannhac.',),('Mức 3 (HSG). Vì sao dùng một tài khoản chung cho mọi nhóm là sai?',),('Mức 3 (HSG). Giải thích SQL injection và cách phòng.',)],
 [('<code>GRANT SELECT ON thuvien.Sach TO guest;</code>',),('Bảo mật: mật khẩu, phân quyền; an toàn: sao lưu, phục hồi.',),('Khách SELECT; thành viên SELECT, INSERT; quản lí UPDATE, DELETE.',),('<code>REVOKE DELETE ON music.bannhac FROM nhom_them;</code>',),('Không phân biệt được người dùng, không truy vết.',),('Ghép chuỗi vào SQL; dùng tham số hoá.',)],hper=2)
